import { unstable_cache } from 'next/cache';

export interface Post {
  id: number;
  title: string;
  content: string;
}

let posts: Post[] = [
  { id: 1, title: 'First Post', content: 'This is the first post.' },
];

export const getPosts = unstable_cache(
  async () => {
    return posts;
  },
  ['posts-cache-key'],
  { tags: ['posts'] }
);

export function addPost(post: Omit<Post, 'id'>) {
  const newPost = {
    id: posts.length + 1,
    ...post,
  };
  posts.push(newPost);
  return newPost;
}

